data a1(keep=gvkey conm tic year fybegdt fyenddt); set comp.funda; 
where consol='C' and indfmt='INDL' and datafmt='STD' and popsrc='D' and curcd = 'USD' and 1985<=fyear<=2017;
fybegdt=intnx('month',datadate,-12,'END')+1;
fyenddt=datadate;
rename fyear=year;
format fybegdt fyenddt date9.; run;

proc sql;
  create table a2 as select
    a.*, b.sic, b.cik, b.naics
  from a1 a left join comp.names b
  on a.gvkey=b.gvkey and
	 b.year1<=a.year<=b.year2; quit;

/*OBTAIN BIG5 DATA*/
proc sql;
  create table a6 as select
    a.*, b.AU
  from a5 a left join comp.co_aaudit b
  on a.gvkey=b.gvkey and
  	 a.fyenddt=b.datadate and 
	 b.consol='C' and b.indfmt='INDL' and b.datafmt='STD' and b.popsrc='D'; quit;

  create table a1 as select
    a.gvkey, a.year, a.permno, a.fybegdt, a.fyenddt, b.ret, b.date
  from index a left join crsp.dsf b
  on a.permno=b.permno and
  	 a.fybegdt<=b.date<=a.fyenddt; quit;
proc sort data=a1 nodupkey; by gvkey year date; run;
proc sql;

  create table a2a as select
    a.*, b.vwretd
  from a1 a, crsp.dsi b
  where a.date=b.date; quit;
proc sort data=a2a nodupkey; by gvkey year date; run;
proc sql;

data rpsample; set raven.ravenpack (keep=RP_ENTITY_ID RPNA_DATE_UTC ENTITY_NAME GROUP COUNTRY_CODE RELEVANCE ESS NIP); 
where relevance=100;
label 	ESS='ESS: EVENT SENTIMENT SCORE'
		NIP='NIP: NEWS IMPACT PROJECTIONS';
format RPNA_DATE_UTC date9.; run;

/*STEP 1: CONVERT THE DATES INTO SAS FORMAT*/
data a1 (drop=range_start range_end); set raven.rp_mapping; where entity_type='COMP' and data_type='CUSIP';
startdate=input(range_start,yymmdd10.);
enddate=range_end;
format startdate enddate date9.; run;

/*OBTAIN TICKER FROM ICLINK FILE: KEEP THE OBSEVATION WITH THE LOWER SCORE WHERE ONE GVKEY MATCHES TO MULTIPLE IBES TICKER*/
proc upload data=iclink out=iclink; run;
proc sql;
  create table a4 as select
    a.gvkey, a.year, a.datadate, a.permno, b.ticker, b.score
  from a3 a left join iclink b
  on a.permno=b.permno; quit;
proc sort data=a4; by gvkey datadate score; run;
proc sort data=a4 nodupkey; by gvkey datadate; run;
data a4; set a4;
if ticker='' then delete; run;

/*OBTAIN ANALYST ESTIMATE FROM IBES ACTUALS FILE*/
proc sql;
  create table a5 as select
    a.*, b.value as eps_ibes, b.actdats
  from a4 a left join ibes.act_epsus b
  on a.ticker=b.ticker and
  	 a.datadate=b.pends and
	 b.measure='EPS' and b.pdicity='QTR' and b.curr_act='USD'; quit;
proc sort data=a5 nodupkey; by gvkey datadate; run;

/*MERGE WITH KURT GEE'S DATASET: Nongaap_data_2003to2020*/
proc sql;
  create table a2 as select
    a.*, b.mgr_exclude, b.MGR_NG_EPS as eps_mgr
  from a1 a left join Nongaap_data_2003to2020 b
  on a.gvkey=b.gvkey and
  	 a.datadate=b.datadate; quit;

