run;
/* Add gvkey and cik that have the same format as historical HQ and Incorporation data */
data slapp.funda_clean (keep = &fundavars); 
set slapp.funda;
gvkey2 = input(gvkey, best12.) ;cik2 = input(cik, best12.) ;
run;

/* Fill missing historical HQ with current ones from Compustat */
proc sql;
 create table a1 as select distinct a.*, b.state as cur_hq
	from slapp.funda_hq a left join slapp.comp_hqinc b on a.gvkey=b.gvkey and a.datadate=b.datadate;
quit;
data a1; set a1; if missing(hq) then hq=cur_hq;run;

/* Add SIC */
proc sql;
 create table a2 as select distinct a.*, b.sic
	from a1 a left join slapp.sic b on a.gvkey=b.gvkey and a.datadate=b.datadate;
quit;

/* Merge sample data and anti slapp enactment year */
proc sql;
 create table a3 as select distinct a.*,b.year as slappyear_hq
	from a2 a left join slapp.slapp b on a.hq=b.st;
quit;

proc sql;
 create table mergeddata2 as select distinct a.*,b.population, b.income_per_capita
	from mergeddata2 a left join slapp.statecontrols b on a.hq=b.abb_ and a.year=b.year;
quit;

proc sql;
 create table mergeddata2 as select distinct a.*,b.medest, b.value
	from mergeddata2 a left join slapp.actu_epsus4 b on a.gvkey=b.gvkey and a.datadate=b.pends;
quit;

proc sql;
 create table mergeddata2 as select distinct a.*,b.skill
	from mergeddata2 a left join slapp.laborskill b on a.year=b.year and a.ind=b.ind;
quit;

quit;
data slapp.shortint; set slapp.shortint;year=year(SPLITADJDATE);month=month(SPLITADJDATE);run;
proc sort data=slapp.shortint; by gvkey year month;run;
data mergeddata2; set mergeddata2;
month=month(datadate);year=year(datadate);run;
proc sql;
 create table mergeddata2_2 as select distinct a.*,b.SHORTINTADJ, b.SHORTINT, b.year as year2, b.month as month2
	from mergeddata2 a left join slapp.shortint b on a.gvkey=b.gvkey and a.datadate-365<b.SPLITADJDATE<=a.datadate;

proc sql;
create table mergeddata2 as
select a.*, b.lpermno as permno
from mergeddata2 as a LEFT JOIN slapp.ccmxpf_lnkhist_3_27 as b                  /*ccm_lnkhist is the linking table downloaded from CRSP/compustat merged*/
on a.gvkey=b.gvkey and b.linkprim in ('P', 'C') and
b.LINKTYPE in ('LU', 'LC') and a.datadate >= b.LINKDT and (a.datadate <= b.LINKENDDT or missing(b.LINKENDDT)) order by gvkey, datadate;

proc sql;
 create table mergeddata2 as select distinct a.*,b.newstone_nonstd
	from mergeddata2 a left join slapp.sentiment b on a.permno=b.permno and a.fyear=b.year;
quit;

proc sql;
 create table mergeddata2 as select distinct a.*,b.NewsCount_nonstd as newscountsum
	from mergeddata2 a left join slapp.sentiment2 b on a.permno=b.permno and a.fyear=b.year;
quit;

proc sql;
 create table mergeddata2 as select distinct a.*, b.*
	from mergeddata2 a left join slapp.nongaap b on a.gvkey=b.gvkey and a.fyear=b.year;
quit;

